   "name": "list_items",
   "operation": "query",
   "sql": "SELECT id, title, done FROM items WHERE org_id IN (SELECT org_id FROM org_members WHERE user_id = :__user_id) ORDER BY created_at DESC LIMIT :limit",
   "params": {
    "limit": {
     "type": "integer",
     "default": 50,
     "max": 100,
     "optional": true
    }
   },
   "requires_auth": true
  },
  {
   "name": "update_item",
   "operation": "execute",
   "sql": "UPDATE items SET done = :done WHERE id = :id",
   "params": {
    "id": {
     "type": "string"
    },
    "done": {
     "type": "boolean"
    }
   },
   "requires_auth": true
  }
 ]
}
